          "id": "code-ml-30-1-ch30_1_sklearn",
          "title": "Scikit-Learn 1.9: Benchmark Profil Kalibrasi Logistic, RandomForest, GaussianNB & MLP",
          "language": "python",
          "filename": "30_1_sklearn_model_family_calibration.py",
          "code": "import numpy as np\nfrom sklearn.calibration import calibration_curve\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.naive_bayes import GaussianNB\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\n# Dataset dengan 8 fitur redundan berkorelasi & label noise 10% (memicu overconfidence tajam di Naive Bayes & MLP!)\nX, y = make_classification(\n    n_samples=2000,\n    n_features=16,\n    n_informative=6,\n    n_redundant=8,\n    n_clusters_per_class=2,\n    flip_y=0.10,\n    class_sep=0.90,\n    random_state=301,\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.35, stratify=y, random_state=42)\n\nmodels = {\n    \"LogisticRegression\": make_pipeline(StandardScaler(), LogisticRegression(C=0.5, max_iter=400)),\n    \"RandomForest (Bagged)\": RandomForestClassifier(n_estimators=100, max_depth=7, min_samples_leaf=5, random_state=42),\n    \"GaussianNB (Indep. Viol.)\": GaussianNB(),\n    \"MLP Modern (Overparam.)\": make_pipeline(\n        StandardScaler(),\n        MLPClassifier(hidden_layer_sizes=(128, 64), alpha=1e-6, max_iter=350, random_state=42),\n    ),\n}\n\n\ndef adaptive_ece(y_true: np.ndarray, probs: np.ndarray, n_bins: int = 10) -> tuple[float, float]:\n    edges = np.quantile(probs, np.linspace(0.0, 1.0, n_bins + 1))\n    edges[0], edges[-1] = 0.0, 1.0\n    ece, mce = 0.0, 0.0\n    for b in range(n_bins):\n        mask = (probs >= edges[b]) & (probs <= edges[b + 1] if b == n_bins - 1 else probs < edges[b + 1])\n        if np.any(mask):\n            gap = abs(float(np.mean(y_true[mask])) - float(np.mean(probs[mask])))\n            ece += (np.sum(mask) / len(y_true)) * gap\n            mce = max(mce, gap)\n    return float(ece), float(mce)\n\n\nprint(f\"=== Komparasi Profil Kalibrasi 4 Keluarga Model (N_test={len(y_te)}) ===\")\nfor name, clf in models.items():\n    clf.fit(X_tr, y_tr)\n    p = clf.predict_proba(X_te)[:, 1]\n    auc_v = roc_auc_score(y_te, p)\n    brier = brier_score_loss(y_te, p)\n    nll = log_loss(y_te, p)\n    ece_q, mce_q = adaptive_ece(y_te, p, n_bins=10)\n    frac_pos, mean_pred = calibration_curve(y_te, p, n_bins=5, strategy=\"quantile\")\n    # Diagnostik ekor atas (kuintil tertinggi): pred - actual > 0 => overconfident, < 0 => underconfident\n    tail_gap = float(mean_pred[-1] - frac_pos[-1])\n    regime = \"OVERCONFIDENT\" if tail_gap > 0.025 else (\"UNDERCONFIDENT\" if tail_gap < -0.025 else \"WELL-CALIBRATED\")\n    print(\n        f\"{name:26s} | AUC={auc_v:.4f} | Brier={brier:.4f} | NLL={nll:.4f} | \"\n        f\"ECE(Q)={ece_q:.4f} | TailGap={tail_gap:+.4f} ({regime})\"\n    )",
          "expectedOutput": "=== Komparasi Profil Kalibrasi 4 Keluarga Model (N_test=700) ===\nLogisticRegression         | AUC=0.7506 | Brier=0.2035 | NLL=0.5947 | ECE(Q)=0.0581 | TailGap=-0.0797 (UNDERCONFIDENT)\nRandomForest (Bagged)      | AUC=0.9145 | Brier=0.1263 | NLL=0.4137 | ECE(Q)=0.1083 | TailGap=-0.0154 (WELL-CALIBRATED)\nGaussianNB (Indep. Viol.)  | AUC=0.7540 | Brier=0.2223 | NLL=0.7177 | ECE(Q)=0.1350 | TailGap=+0.1261 (OVERCONFIDENT)\nMLP Modern (Overparam.)    | AUC=0.9183 | Brier=0.1361 | NLL=0.6228 | ECE(Q)=0.1170 | TailGap=+0.0428 (OVERCONFIDENT)",
          "actualOutput": "=== Komparasi Profil Kalibrasi 4 Keluarga Model (N_test=700) ===\nLogisticRegression         | AUC=0.7506 | Brier=0.2035 | NLL=0.5947 | ECE(Q)=0.0581 | TailGap=-0.0797 (UNDERCONFIDENT)\nRandomForest (Bagged)      | AUC=0.9145 | Brier=0.1263 | NLL=0.4137 | ECE(Q)=0.1083 | TailGap=-0.0154 (WELL-CALIBRATED)\nGaussianNB (Indep. Viol.)  | AUC=0.7540 | Brier=0.2223 | NLL=0.7177 | ECE(Q)=0.1350 | TailGap=+0.1261 (OVERCONFIDENT)\nMLP Modern (Overparam.)    | AUC=0.9183 | Brier=0.1361 | NLL=0.6228 | ECE(Q)=0.1170 | TailGap=+0.0428 (OVERCONFIDENT)",
          "explanation": "Membandingkan kurva reliabilitas kuantil, Brier Score, Log-Loss, Adaptive ECE, dan tail gap keempat keluarga model pada fitur berkorelasi (memperlihatkan pola underconfident Random Forest vs overconfident GaussianNB dan MLP).",
