          "code": "import numpy as np\n\nrng = np.random.default_rng(3019)\n\n# -----------------------------------------------------------------------------\n# Production Audit: Mengapa Uniform ECE Bisa Menipu pada Distribusi Pincang\n# (85% transaksi risiko rendah p < 0.08, 15% segmen kredit premium berisiko tinggi)\n# -----------------------------------------------------------------------------\nn_low, n_high = 3400, 600\np_low_true = rng.beta(1.5, 45.0, size=n_low)        # rata-rata ~3.2%\np_high_true = rng.beta(4.0, 6.0, size=n_high)       # rata-rata ~40.0%\ny_low = rng.binomial(1, p_low_true)\ny_high = rng.binomial(1, p_high_true)\n\n# Model produksi bagus di segmen massal, tetapi overconfident parah +22% di segmen risiko tinggi!\np_low_pred = np.clip(p_low_true + rng.normal(0.0, 0.004, n_low), 0.001, 0.999)\np_high_pred = np.clip(p_high_true + 0.22, 0.001, 0.995)\n\ny_all = np.concatenate([y_low, y_high])\np_all = np.concatenate([p_low_pred, p_high_pred])\n\n\ndef bin_diagnostics(y_true: np.ndarray, probs: np.ndarray, n_bins: int, strategy: str) -> dict:\n    if strategy == \"uniform\":\n        edges = np.linspace(0.0, 1.0, n_bins + 1)\n    else:\n        edges = np.quantile(probs, np.linspace(0.0, 1.0, n_bins + 1))\n        edges[0], edges[-1] = 0.0, 1.0\n    ece, mce, min_cnt, max_cnt = 0.0, 0.0, 10**9, 0\n    for b in range(n_bins):\n        mask = (probs >= edges[b]) & (probs <= edges[b + 1] if b == n_bins - 1 else probs < edges[b + 1])\n        cnt = int(np.sum(mask))\n        if cnt == 0:\n            continue\n        gap = abs(float(np.mean(y_true[mask])) - float(np.mean(probs[mask])))\n        ece += (cnt / len(y_true)) * gap\n        mce = max(mce, gap)\n        min_cnt = min(min_cnt, cnt)\n        max_cnt = max(max_cnt, cnt)\n    return {\"ece\": ece, \"mce\": mce, \"min_bin_n\": min_cnt, \"max_bin_n\": max_cnt}\n\n\nu_diag = bin_diagnostics(y_all, p_all, n_bins=10, strategy=\"uniform\")\nq_diag = bin_diagnostics(y_all, p_all, n_bins=10, strategy=\"quantile\")\n\nprint(\"=== Audit Uniform vs Quantile Binning + Subgroup Calibration ===\")\nprint(\n    f\"Uniform 10-Bin  | ECE={u_diag['ece']:.4f} | MCE={u_diag['mce']:.4f} | \"\n    f\"Bin Count Min={u_diag['min_bin_n']:4d}, Max={u_diag['max_bin_n']:4d}\"\n)\nprint(\n    f\"Quantile 10-Bin | ECE={q_diag['ece']:.4f} | MCE={q_diag['mce']:.4f} | \"\n    f\"Bin Count Min={q_diag['min_bin_n']:4d}, Max={q_diag['max_bin_n']:4d}\"\n)\nprint(\n    f\"Global Calibration-in-the-Large: MeanPred={p_all.mean():.4f} vs Actual={y_all.mean():.4f} \"\n    f\"(Signed Bias={p_all.mean() - y_all.mean():+.4f})\"\n)\nprint(\n    f\"Segmen Massal  (n={n_low:4d}): MeanPred={p_low_pred.mean():.4f} | Actual={y_low.mean():.4f} | \"\n    f\"Bias={p_low_pred.mean() - y_low.mean():+.4f}\"\n)\nprint(\n    f\"Segmen Risiko  (n={n_high:4d}): MeanPred={p_high_pred.mean():.4f} | Actual={y_high.mean():.4f} | \"\n    f\"Bias={p_high_pred.mean() - y_high.mean():+.4f}  <-- BAHAYA MISPRICING!\"\n)",
          "expectedOutput": "=== Audit Uniform vs Quantile Binning + Subgroup Calibration ===\nUniform 10-Bin  | ECE=0.0358 | MCE=0.3171 | Bin Count Min=   3, Max=3317\nQuantile 10-Bin | ECE=0.0378 | MCE=0.2117 | Bin Count Min= 400, Max= 400\nGlobal Calibration-in-the-Large: MeanPred=0.1193 vs Actual=0.0835 (Signed Bias=+0.0358)\nSegmen Massal  (n=3400): MeanPred=0.0323 | Actual=0.0288 | Bias=+0.0034\nSegmen Risiko  (n= 600): MeanPred=0.6123 | Actual=0.3933 | Bias=+0.2189  <-- BAHAYA MISPRICING!",
          "actualOutput": "=== Audit Uniform vs Quantile Binning + Subgroup Calibration ===\nUniform 10-Bin  | ECE=0.0358 | MCE=0.3171 | Bin Count Min=   3, Max=3317\nQuantile 10-Bin | ECE=0.0378 | MCE=0.2117 | Bin Count Min= 400, Max= 400\nGlobal Calibration-in-the-Large: MeanPred=0.1193 vs Actual=0.0835 (Signed Bias=+0.0358)\nSegmen Massal  (n=3400): MeanPred=0.0323 | Actual=0.0288 | Bias=+0.0034\nSegmen Risiko  (n= 600): MeanPred=0.6123 | Actual=0.3933 | Bias=+0.2189  <-- BAHAYA MISPRICING!",
