          "code": "import numpy as np\nfrom scipy.optimize import minimize_scalar\n\nrng = np.random.default_rng(302)\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy/SciPy:\n# 1) Multiclass Temperature Scaling (melestarikan 100% Top-1 Akurasi!)\n# 2) PAVA (Pool Adjacent Violators Algorithm) Isotonic Regression dari nol\n# 3) Inductive Venn-Abers Predictor (IVAP) -> interval [p0, p1] + p_VA\n# -----------------------------------------------------------------------------\nn_cal_mc, n_test_mc, K = 1000, 1000, 5\ntrue_logits_cal = rng.normal(0.0, 1.3, size=(n_cal_mc, K))\ntrue_logits_test = rng.normal(0.0, 1.3, size=(n_test_mc, K))\n\n\ndef softmax(z: np.ndarray) -> np.ndarray:\n    z_shift = z - np.max(z, axis=1, keepdims=True)\n    e = np.exp(z_shift)\n    return e / np.sum(e, axis=1, keepdims=True)\n\n\np_true_cal = softmax(true_logits_cal)\np_true_test = softmax(true_logits_test)\ny_cal_mc = np.array([rng.choice(K, p=row) for row in p_true_cal])\ny_test_mc = np.array([rng.choice(K, p=row) for row in p_true_test])\n\n# Jaringan saraf overconfident mengeluarkan logit 2.6x lebih tajam daripada logit sejati!\nraw_logits_cal = 2.6 * true_logits_cal\nraw_logits_test = 2.6 * true_logits_test\n\n\ndef mc_nll(logits: np.ndarray, y: np.ndarray, T: float) -> float:\n    probs = softmax(logits / T)\n    return float(-np.mean(np.log(np.clip(probs[np.arange(len(y)), y], 1e-12, 1.0))))\n\n\ndef mc_conf_ece(probs: np.ndarray, y: np.ndarray, n_bins: int = 10) -> float:\n    conf = np.max(probs, axis=1)\n    acc = (np.argmax(probs, axis=1) == y).astype(float)\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    for b in range(n_bins):\n        mask = (conf >= edges[b]) & (conf <= edges[b + 1] if b == n_bins - 1 else conf < edges[b + 1])\n        if np.any(mask):\n            ece += (np.sum(mask) / len(y)) * abs(float(np.mean(acc[mask])) - float(np.mean(conf[mask])))\n    return float(ece)\n\n\nopt = minimize_scalar(lambda T: mc_nll(raw_logits_cal, y_cal_mc, T), bounds=(0.1, 10.0), method=\"bounded\")\nT_star = float(opt.x)\np_before = softmax(raw_logits_test)\np_after = softmax(raw_logits_test / T_star)\nacc_before = float(np.mean(np.argmax(p_before, axis=1) == y_test_mc))\nacc_after = float(np.mean(np.argmax(p_after, axis=1) == y_test_mc))\n\nprint(\"=== 1) Multiclass Temperature Scaling (K=5, Logit Overconfident 2.6x) ===\")\nprint(f\"Optimal Temperature T* : {T_star:.4f} (Target Teoretis ~ 2.60)\")\nprint(f\"Sebelum (T=1.00)       : Acc={acc_before:.4f} | NLL={mc_nll(raw_logits_test, y_test_mc, 1.0):.4f} | ECE={mc_conf_ece(p_before, y_test_mc):.4f}\")\nprint(f\"Sesudah (T={T_star:.2f})       : Acc={acc_after:.4f} | NLL={mc_nll(raw_logits_test, y_test_mc, T_star):.4f} | ECE={mc_conf_ece(p_after, y_test_mc):.4f}\")\nprint(f\"Argmax Identik 100%?   : {bool(np.array_equal(np.argmax(p_before, axis=1), np.argmax(p_after, axis=1)))}\")\n\n\n# 2) PAVA Isotonic Regression & 3) Inductive Venn-Abers Predictor (IVAP)\ndef pava_isotonic(y_sorted: np.ndarray) -> np.ndarray:\n    \"\"\"Pool Adjacent Violators Algorithm O(n) untuk regresi monoton non-menurun.\"\"\"\n    blocks: list[list[float]] = []  # [sum_y, count]\n    for val in y_sorted:\n        blocks.append([float(val), 1.0])\n        while len(blocks) >= 2 and (blocks[-2][0] / blocks[-2][1]) > (blocks[-1][0] / blocks[-1][1]):\n            b_last = blocks.pop()\n            blocks[-1][0] += b_last[0]\n            blocks[-1][1] += b_last[1]\n    out = np.empty(len(y_sorted), dtype=float)\n    pos = 0\n    for s_val, cnt in blocks:\n        c = int(cnt)\n        out[pos : pos + c] = s_val / cnt\n        pos += c\n    return out\n\n\ndef venn_abers_predict(s_cal: np.ndarray, y_cal: np.ndarray, s_new: float) -> tuple[float, float, float]:\n    \"\"\"Inductive Venn-Abers: pasang (s_new, 0) dan (s_new, 1) -> hasilkan [p0, p1] & p_VA.\"\"\"\n    res = []\n    for cand_y in (0.0, 1.0):\n        s_aug = np.append(s_cal, s_new)\n        y_aug = np.append(y_cal, cand_y)\n        order = np.argsort(s_aug, kind=\"mergesort\")\n        iso = pava_isotonic(y_aug[order])\n        new_pos = int(np.where(order == len(s_cal))[0][0])\n        res.append(float(iso[new_pos]))\n    p0, p1 = res[0], res[1]\n    p_va = p1 / (1.0 - p0 + p1)\n    return p0, p1, p_va\n\n\ns_cal_va = rng.normal(0.0, 1.0, size=200)\ny_cal_va = rng.binomial(1, 1.0 / (1.0 + np.exp(-1.5 * s_cal_va)))\n\nprint(\"\\n=== 2) Inductive Venn-Abers Interval [p0, p1] (n_cal=200) ===\")\nfor tag, s_query in [(\"Daerah Padat (s=0.0)\", 0.0), (\"Daerah Sedang (s=1.2)\", 1.2), (\"Ekor Jarang (s=3.2)\", 3.2)]:\n    p0, p1, p_va = venn_abers_predict(s_cal_va, y_cal_va, s_query)\n    print(f\"  {tag:23s} -> [p0={p0:.4f}, p1={p1:.4f}] | Lebar Epistemik={p1 - p0:.4f} | p_VA={p_va:.4f}\")",
          "expectedOutput": "=== 1) Multiclass Temperature Scaling (K=5, Logit Overconfident 2.6x) ===\nOptimal Temperature T* : 2.6648 (Target Teoretis ~ 2.60)\nSebelum (T=1.00)       : Acc=0.5350 | NLL=1.5491 | ECE=0.2369\nSesudah (T=2.66)       : Acc=0.5350 | NLL=1.1601 | ECE=0.0400\nArgmax Identik 100%?   : True\n\n=== 2) Inductive Venn-Abers Interval [p0, p1] (n_cal=200) ===\n  Daerah Padat (s=0.0)    -> [p0=0.5156, p1=0.5312] | Lebar Epistemik=0.0156 | p_VA=0.5231\n  Daerah Sedang (s=1.2)   -> [p0=0.7895, p1=0.8158] | Lebar Epistemik=0.0263 | p_VA=0.7949\n  Ekor Jarang (s=3.2)     -> [p0=0.8824, p1=1.0000] | Lebar Epistemik=0.1176 | p_VA=0.8947",
          "actualOutput": "=== 1) Multiclass Temperature Scaling (K=5, Logit Overconfident 2.6x) ===\nOptimal Temperature T* : 2.6648 (Target Teoretis ~ 2.60)\nSebelum (T=1.00)       : Acc=0.5350 | NLL=1.5491 | ECE=0.2369\nSesudah (T=2.66)       : Acc=0.5350 | NLL=1.1601 | ECE=0.0400\nArgmax Identik 100%?   : True\n\n=== 2) Inductive Venn-Abers Interval [p0, p1] (n_cal=200) ===\n  Daerah Padat (s=0.0)    -> [p0=0.5156, p1=0.5312] | Lebar Epistemik=0.0156 | p_VA=0.5231\n  Daerah Sedang (s=1.2)   -> [p0=0.7895, p1=0.8158] | Lebar Epistemik=0.0263 | p_VA=0.7949\n  Ekor Jarang (s=3.2)     -> [p0=0.8824, p1=1.0000] | Lebar Epistemik=0.1176 | p_VA=0.8947",
