          "id": "code-ml-30-2-ch30_2_sklearn",
          "title": "Scikit-Learn 1.6+: CalibratedClassifierCV(FrozenEstimator) di Small vs Large Calibration Split",
          "language": "python",
          "filename": "30_2_sklearn_frozen_platt_vs_isotonic.py",
          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.naive_bayes import GaussianNB\n\n# Dataset dengan fitur berkorelasi (membuat GaussianNB sangat miscalibrated!)\nX, y = make_classification(\n    n_samples=4600,\n    n_features=16,\n    n_informative=6,\n    n_redundant=8,\n    flip_y=0.04,\n    class_sep=0.95,\n    random_state=302,\n)\nX_tr, X_rest, y_tr, y_rest = train_test_split(X, y, test_size=0.65, stratify=y, random_state=42)\nX_cal_big, X_te, y_cal_big, y_te = train_test_split(X_rest, y_rest, test_size=0.35, stratify=y_rest, random_state=42)\n# Subset kalibrasi kecil (n_cal=200) untuk menguji overfitting Isotonic vs ketahanan Platt!\nX_cal_small, y_cal_small = X_cal_big[:200], y_cal_big[:200]\n\n\ndef quantile_ece(y_true: np.ndarray, probs: np.ndarray, n_bins: int = 10) -> float:\n    edges = np.quantile(probs, np.linspace(0.0, 1.0, n_bins + 1))\n    edges[0], edges[-1] = 0.0, 1.0\n    ece = 0.0\n    for b in range(n_bins):\n        mask = (probs >= edges[b]) & (probs <= edges[b + 1] if b == n_bins - 1 else probs < edges[b + 1])\n        if np.any(mask):\n            ece += (np.sum(mask) / len(y_true)) * abs(float(np.mean(y_true[mask])) - float(np.mean(probs[mask])))\n    return float(ece)\n\n\nbase_nb = GaussianNB().fit(X_tr, y_tr)\np_raw = base_nb.predict_proba(X_te)[:, 1]\nprint(f\"=== Scikit-Learn 1.6+ CalibratedClassifierCV(FrozenEstimator) (N_test={len(y_te)}) ===\")\nprint(\n    f\"Raw GaussianNB (Uncalibrated)      | AUC={roc_auc_score(y_te, p_raw):.4f} | \"\n    f\"Brier={brier_score_loss(y_te, p_raw):.4f} | NLL={log_loss(y_te, p_raw):.4f} | ECE={quantile_ece(y_te, p_raw):.4f}\"\n)\n\nfor tag, Xc, yc in [\n    (f\"Small Cal (n={len(y_cal_small)})\", X_cal_small, y_cal_small),\n    (f\"Large Cal (n={len(y_cal_big)})\", X_cal_big, y_cal_big),\n]:\n    for method in (\"sigmoid\", \"isotonic\"):\n        cal = CalibratedClassifierCV(FrozenEstimator(base_nb), method=method)\n        cal.fit(Xc, yc)\n        p_c = cal.predict_proba(X_te)[:, 1]\n        print(\n            f\"{tag:18s} + {method:8s}      | AUC={roc_auc_score(y_te, p_c):.4f} | \"\n            f\"Brier={brier_score_loss(y_te, p_c):.4f} | NLL={log_loss(y_te, p_c):.4f} | ECE={quantile_ece(y_te, p_c):.4f}\"\n        )\n\n# Bonus: Out-of-fold CV Calibration pada GBDT tanpa perlu mengorbankan split kalibrasi terpisah\ngbdt_cv = CalibratedClassifierCV(\n    HistGradientBoostingClassifier(max_iter=70, max_depth=4, random_state=42),\n    method=\"sigmoid\",\n    cv=5,\n)\ngbdt_cv.fit(X_tr, y_tr)\np_gbdt = gbdt_cv.predict_proba(X_te)[:, 1]\nprint(\n    f\"HistGBDT + CV=5 Sigmoid (OOF)      | AUC={roc_auc_score(y_te, p_gbdt):.4f} | \"\n    f\"Brier={brier_score_loss(y_te, p_gbdt):.4f} | NLL={log_loss(y_te, p_gbdt):.4f} | ECE={quantile_ece(y_te, p_gbdt):.4f}\"\n)",
          "expectedOutput": "=== Scikit-Learn 1.6+ CalibratedClassifierCV(FrozenEstimator) (N_test=1047) ===\nRaw GaussianNB (Uncalibrated)      | AUC=0.9252 | Brier=0.1102 | NLL=0.5221 | ECE=0.0716\nSmall Cal (n=200)  + sigmoid       | AUC=0.9252 | Brier=0.1060 | NLL=0.3562 | ECE=0.0428\nSmall Cal (n=200)  + isotonic      | AUC=0.9225 | Brier=0.1054 | NLL=0.6214 | ECE=0.0382\nLarge Cal (n=1943) + sigmoid       | AUC=0.9252 | Brier=0.1056 | NLL=0.3560 | ECE=0.0460\nLarge Cal (n=1943) + isotonic      | AUC=0.9247 | Brier=0.1044 | NLL=0.3759 | ECE=0.0206\nHistGBDT + CV=5 Sigmoid (OOF)      | AUC=0.9762 | Brier=0.0437 | NLL=0.1712 | ECE=0.0203",
          "actualOutput": "=== Scikit-Learn 1.6+ CalibratedClassifierCV(FrozenEstimator) (N_test=1047) ===\nRaw GaussianNB (Uncalibrated)      | AUC=0.9252 | Brier=0.1102 | NLL=0.5221 | ECE=0.0716\nSmall Cal (n=200)  + sigmoid       | AUC=0.9252 | Brier=0.1060 | NLL=0.3562 | ECE=0.0428\nSmall Cal (n=200)  + isotonic      | AUC=0.9225 | Brier=0.1054 | NLL=0.6214 | ECE=0.0382\nLarge Cal (n=1943) + sigmoid       | AUC=0.9252 | Brier=0.1056 | NLL=0.3560 | ECE=0.0460\nLarge Cal (n=1943) + isotonic      | AUC=0.9247 | Brier=0.1044 | NLL=0.3759 | ECE=0.0206\nHistGBDT + CV=5 Sigmoid (OOF)      | AUC=0.9762 | Brier=0.0437 | NLL=0.1712 | ECE=0.0203",
