          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.isotonic import IsotonicRegression\nfrom sklearn.metrics import brier_score_loss, log_loss\nfrom sklearn.model_selection import train_test_split\n\n# -----------------------------------------------------------------------------\n# Production Audit: Bencana Overfit Mengkalibrasi Isotonic di X_train yang Sama\n# dengan GBDT vs Kalibrasi Sah pada Held-Out Split via FrozenEstimator\n# -----------------------------------------------------------------------------\nX, y = make_classification(\n    n_samples=3000,\n    n_features=20,\n    n_informative=8,\n    n_redundant=4,\n    flip_y=0.08,\n    class_sep=0.85,\n    random_state=3029,\n)\nX_tr, X_tmp, y_tr, y_tmp = train_test_split(X, y, test_size=0.50, stratify=y, random_state=42)\nX_cal, X_te, y_cal, y_te = train_test_split(X_tmp, y_tmp, test_size=0.50, stratify=y_tmp, random_state=42)\n\n\ndef ece_10(y_true: np.ndarray, probs: np.ndarray) -> float:\n    edges = np.quantile(probs, np.linspace(0.0, 1.0, 11))\n    edges[0], edges[-1] = 0.0, 1.0\n    ece = 0.0\n    for b in range(10):\n        m = (probs >= edges[b]) & (probs <= edges[b + 1] if b == 9 else probs < edges[b + 1])\n        if np.any(m):\n            ece += (np.sum(m) / len(y_true)) * abs(float(np.mean(y_true[m])) - float(np.mean(probs[m])))\n    return float(ece)\n\n\n# GBDT berkapasitas tinggi (hafal sebagian besar X_train)\ngbdt = HistGradientBoostingClassifier(\n    max_iter=180, max_depth=8, min_samples_leaf=5, learning_rate=0.12, random_state=42\n).fit(X_tr, y_tr)\n\np_tr_raw = gbdt.predict_proba(X_tr)[:, 1]\np_te_raw = gbdt.predict_proba(X_te)[:, 1]\n\n# ANTI-PATTERN: Melatih IsotonicRegression di X_train yang sama!\niso_leaky = IsotonicRegression(out_of_bounds=\"clip\").fit(p_tr_raw, y_tr)\np_te_leaky = np.clip(iso_leaky.transform(p_te_raw), 1e-6, 1.0 - 1e-6)\n\n# PRODUCTION-SAFE: FrozenEstimator + held-out calibration split\niso_safe = CalibratedClassifierCV(FrozenEstimator(gbdt), method=\"isotonic\").fit(X_cal, y_cal)\np_te_iso_safe = iso_safe.predict_proba(X_te)[:, 1]\n\nplatt_safe = CalibratedClassifierCV(FrozenEstimator(gbdt), method=\"sigmoid\").fit(X_cal, y_cal)\np_te_platt_safe = platt_safe.predict_proba(X_te)[:, 1]\n\nprint(f\"=== Audit Leakage Kalibrasi GBDT (Train NLL={log_loss(y_tr, p_tr_raw):.4f}) ===\")\nfor label, p in [\n    (\"1. Raw GBDT (Tanpa Kalibrasi)\", p_te_raw),\n    (\"2. LEAKY Isotonic di X_train\", p_te_leaky),\n    (\"3. SAFE Isotonic (Held-Out)\", p_te_iso_safe),\n    (\"4. SAFE Platt/Sigmoid (Held-Out)\", p_te_platt_safe),\n]:\n    print(f\"{label:34s} | Test Brier={brier_score_loss(y_te, p):.4f} | Test NLL={log_loss(y_te, p):.4f} | Test ECE={ece_10(y_te, p):.4f}\")",
