          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier, HistGradientBoostingRegressor\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(3031)\n\n# -----------------------------------------------------------------------------\n# Bagian A: Split Conformal Regression untuk ETA Pengiriman (Target 90% SLA)\n# -----------------------------------------------------------------------------\nn_reg = 2400\nX_reg = rng.uniform(0.5, 25.0, size=(n_reg, 4))  # jarak, kepadatan, cuaca, beban_dapur\neta_base = 8.0 + 1.4 * X_reg[:, 0] + 0.6 * X_reg[:, 1] + 0.25 * (X_reg[:, 2] ** 1.5)\n# Noise miring kanan (kemacetan tak terduga)\neta_y = eta_base + rng.gamma(shape=2.2, scale=2.5, size=n_reg)\n\nX_r_tr, X_r_rest, y_r_tr, y_r_rest = train_test_split(X_reg, eta_y, test_size=0.50, random_state=42)\nX_r_cal, X_r_te, y_r_cal, y_r_te = train_test_split(X_r_rest, y_r_rest, test_size=0.50, random_state=42)\n\nreg = HistGradientBoostingRegressor(max_iter=80, max_depth=4, random_state=42).fit(X_r_tr, y_r_tr)\nscores_reg = np.abs(y_r_cal - reg.predict(X_r_cal))\nalpha = 0.10\nn_cal_r = len(scores_reg)\nq_reg = float(np.quantile(scores_reg, np.ceil((n_cal_r + 1) * (1 - alpha)) / n_cal_r, method=\"higher\"))\n\npred_te = reg.predict(X_r_te)\nlo_te, hi_te = pred_te - q_reg, pred_te + q_reg\ncov_reg = float(np.mean((y_r_te >= lo_te) & (y_r_te <= hi_te)))\n\nprint(\"=== Bagian A: Split Conformal Regression (HistGBDT ETA, Target 90%) ===\")\nprint(f\"n_cal={n_cal_r} | q_hat={q_reg:.3f} menit | Lebar Pita={2 * q_reg:.3f} menit | Empirical Coverage={cov_reg:.4f}\")\n\n# -----------------------------------------------------------------------------\n# Bagian B: Split Conformal Multiclass Prediction Sets (LAC: s = 1 - p_y)\n# -----------------------------------------------------------------------------\nX_c, y_c = make_classification(\n    n_samples=2000,\n    n_features=12,\n    n_informative=7,\n    n_redundant=2,\n    n_classes=4,\n    n_clusters_per_class=1,\n    flip_y=0.05,\n    class_sep=0.90,\n    random_state=303,\n)\nX_c_tr, X_c_rest, y_c_tr, y_c_rest = train_test_split(X_c, y_c, test_size=0.50, stratify=y_c, random_state=42)\nX_c_cal, X_c_te, y_c_cal, y_c_te = train_test_split(X_c_rest, y_c_rest, test_size=0.50, stratify=y_c_rest, random_state=42)\n\nclf = HistGradientBoostingClassifier(max_iter=60, max_depth=4, random_state=42).fit(X_c_tr, y_c_tr)\nprobs_cal = clf.predict_proba(X_c_cal)\nscores_clf = 1.0 - probs_cal[np.arange(len(y_c_cal)), y_c_cal]\nn_cal_c = len(scores_clf)\nq_clf = float(np.quantile(scores_clf, np.ceil((n_cal_c + 1) * (1 - alpha)) / n_cal_c, method=\"higher\"))\n\nprobs_te = clf.predict_proba(X_c_te)\npred_sets = probs_te >= (1.0 - q_clf)\ncov_clf = float(np.mean(pred_sets[np.arange(len(y_c_te)), y_c_te]))\nset_sizes = pred_sets.sum(axis=1)\ntop1_acc = float(np.mean(np.argmax(probs_te, axis=1) == y_c_te))\n\nprint(\"\\n=== Bagian B: Split Conformal Prediction Sets (4 Kelas, Target 90%) ===\")\nprint(f\"Top-1 Akurasi={top1_acc:.4f} | Threshold Prob >= {1 - q_clf:.4f} | Empirical Set Coverage={cov_clf:.4f}\")\nprint(\n    f\"Distribusi Ukuran Set: |C|=0: {(set_sizes==0).mean():.1%} | |C|=1: {(set_sizes==1).mean():.1%} | \"\n    f\"|C|=2: {(set_sizes==2).mean():.1%} | |C|>=3: {(set_sizes>=3).mean():.1%} | Avg Size={set_sizes.mean():.3f}\"\n)",
          "expectedOutput": "=== Bagian A: Split Conformal Regression (HistGBDT ETA, Target 90%) ===\nn_cal=600 | q_hat=6.009 menit | Lebar Pita=12.019 menit | Empirical Coverage=0.8900\n\n=== Bagian B: Split Conformal Prediction Sets (4 Kelas, Target 90%) ===\nTop-1 Akurasi=0.7660 | Threshold Prob >= 0.1436 | Empirical Set Coverage=0.9060\nDistribusi Ukuran Set: |C|=0: 0.0% | |C|=1: 61.4% | |C|=2: 26.8% | |C|>=3: 11.8% | Avg Size=1.512",
          "actualOutput": "=== Bagian A: Split Conformal Regression (HistGBDT ETA, Target 90%) ===\nn_cal=600 | q_hat=6.009 menit | Lebar Pita=12.019 menit | Empirical Coverage=0.8900\n\n=== Bagian B: Split Conformal Prediction Sets (4 Kelas, Target 90%) ===\nTop-1 Akurasi=0.7660 | Threshold Prob >= 0.1436 | Empirical Set Coverage=0.9060\nDistribusi Ukuran Set: |C|=0: 0.0% | |C|=1: 61.4% | |C|=2: 26.8% | |C|>=3: 11.8% | Avg Size=1.512",
