          "id": "code-ml-30-4-ch30_4_sklearn",
          "title": "Scikit-Learn HistGBDT: Pipeline CQR Quantile & Perbandingan APS vs LAC pada 5 Kelas",
          "language": "python",
          "filename": "30_4_sklearn_cqr_and_aps_multiclass.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier, HistGradientBoostingRegressor\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(3041)\n\n# -----------------------------------------------------------------------------\n# Bagian A: CQR Produksi dengan HistGradientBoostingRegressor(loss=\"quantile\")\n# -----------------------------------------------------------------------------\nn = 1800\nX = rng.uniform(0.0, 10.0, size=(n, 3))\nsignal = 10.0 + 2.0 * np.sin(0.8 * X[:, 0]) + 0.7 * X[:, 1]\nnoise_scale = 0.5 + 0.55 * X[:, 0]  # Heteroskedastisitas kuat sepanjang fitur X[:, 0]\ny = signal + noise_scale * rng.standard_normal(size=n)\n\nX_tr, X_rest, y_tr, y_rest = train_test_split(X, y, test_size=0.50, random_state=42)\nX_cal, X_te, y_cal, y_te = train_test_split(X_rest, y_rest, test_size=0.50, random_state=42)\n\nalpha = 0.10\nm_mean = HistGradientBoostingRegressor(loss=\"squared_error\", max_iter=60, max_depth=4, random_state=42).fit(X_tr, y_tr)\nm_lo = HistGradientBoostingRegressor(loss=\"quantile\", quantile=alpha / 2, max_iter=60, max_depth=4, random_state=42).fit(X_tr, y_tr)\nm_hi = HistGradientBoostingRegressor(loss=\"quantile\", quantile=1 - alpha / 2, max_iter=60, max_depth=4, random_state=42).fit(X_tr, y_tr)\n\nq_lvl = np.ceil((len(y_cal) + 1) * (1 - alpha)) / len(y_cal)\n# Split Conformal Konstan\nq_sc = float(np.quantile(np.abs(y_cal - m_mean.predict(X_cal)), q_lvl, method=\"higher\"))\nmu_te = m_mean.predict(X_te)\nhit_sc = (y_te >= mu_te - q_sc) & (y_te <= mu_te + q_sc)\n\n# CQR\nql_c, qh_c = np.minimum(m_lo.predict(X_cal), m_hi.predict(X_cal)), np.maximum(m_lo.predict(X_cal), m_hi.predict(X_cal))\nE_cal = np.maximum(ql_c - y_cal, y_cal - qh_c)\nq_cqr = float(np.quantile(E_cal, q_lvl, method=\"higher\"))\nql_t, qh_t = np.minimum(m_lo.predict(X_te), m_hi.predict(X_te)), np.maximum(m_lo.predict(X_te), m_hi.predict(X_te))\nlo_cqr, hi_cqr = ql_t - q_cqr, qh_t + q_cqr\nhit_cqr = (y_te >= lo_cqr) & (y_te <= hi_cqr)\n\nhi_var_mask = X_te[:, 0] > 7.5\nlo_var_mask = X_te[:, 0] < 2.5\n\nprint(\"=== Bagian A: Scikit-Learn HistGBDT Quantile -> CQR vs Split Conformal ===\")\nprint(\n    f\"Split Conformal (Konstan) | Marg={hit_sc.mean():.3f} | LowVar={hit_sc[lo_var_mask].mean():.3f} | \"\n    f\"HighVar={hit_sc[hi_var_mask].mean():.3f} | AvgW={2 * q_sc:.2f}\"\n)\nprint(\n    f\"CQR Adaptif (Q={q_cqr:+.3f})   | Marg={hit_cqr.mean():.3f} | LowVar={hit_cqr[lo_var_mask].mean():.3f} | \"\n    f\"HighVar={hit_cqr[hi_var_mask].mean():.3f} | AvgW={(hi_cqr - lo_cqr).mean():.2f}\"\n)\n\n# -----------------------------------------------------------------------------\n# Bagian B: Randomized Adaptive Prediction Sets (APS) vs LAC pada 5 Kelas\n# -----------------------------------------------------------------------------\nXc, yc = make_classification(\n    n_samples=1800, n_features=12, n_informative=8, n_redundant=2,\n    n_classes=5, n_clusters_per_class=1, flip_y=0.05, class_sep=0.95, random_state=304,\n)\nXc_tr, Xc_rest, yc_tr, yc_rest = train_test_split(Xc, yc, test_size=0.50, stratify=yc, random_state=42)\nXc_cal, Xc_te, yc_cal, yc_te = train_test_split(Xc_rest, yc_rest, test_size=0.50, stratify=yc_rest, random_state=42)\n\nclf = HistGradientBoostingClassifier(max_iter=55, max_depth=4, random_state=42).fit(Xc_tr, yc_tr)\npc_cal = clf.predict_proba(Xc_cal)\npc_te = clf.predict_proba(Xc_te)\n\n\ndef aps_scores_randomized(probs: np.ndarray, y_true: np.ndarray, u: np.ndarray) -> np.ndarray:\n    order = np.argsort(-probs, axis=1)\n    sorted_p = np.take_along_axis(probs, order, axis=1)\n    cum_p = np.cumsum(sorted_p, axis=1)\n    ranks = np.where(order == y_true[:, None])[1]\n    cum_before = cum_p[np.arange(len(y_true)), ranks] - sorted_p[np.arange(len(y_true)), ranks]\n    return cum_before + u * sorted_p[np.arange(len(y_true)), ranks]\n\n\ndef aps_predict_sets_randomized(probs: np.ndarray, q_hat: float, u: np.ndarray) -> np.ndarray:\n    order = np.argsort(-probs, axis=1)\n    sorted_p = np.take_along_axis(probs, order, axis=1)\n    cum_before = np.cumsum(sorted_p, axis=1) - sorted_p\n    scores_all = cum_before + u[:, None] * sorted_p\n    keep_sorted = scores_all <= q_hat\n    keep_sorted[:, 0] = True  # jamin set tidak kosong\n    sets = np.zeros_like(probs, dtype=bool)\n    np.put_along_axis(sets, order, keep_sorted, axis=1)\n    return sets\n\n\nq_lvl_c = np.ceil((len(yc_cal) + 1) * (1 - alpha)) / len(yc_cal)\n# LAC\nq_lac = float(np.quantile(1.0 - pc_cal[np.arange(len(yc_cal)), yc_cal], q_lvl_c, method=\"higher\"))\nsets_lac = pc_te >= (1.0 - q_lac)\n# Randomized APS (Romano, Sesia & Candes 2020)\nu_cal = rng.uniform(0.0, 1.0, size=len(yc_cal))\nu_te = rng.uniform(0.0, 1.0, size=len(yc_te))\nq_aps = float(np.quantile(aps_scores_randomized(pc_cal, yc_cal, u_cal), q_lvl_c, method=\"higher\"))\nsets_aps = aps_predict_sets_randomized(pc_te, q_aps, u_te)\n\n# Identifikasi sampel sulit (entropi tinggi / max prob < 0.70)\nhard_mask = pc_te.max(axis=1) < 0.70\ncov_lac_all = float(np.mean(sets_lac[np.arange(len(yc_te)), yc_te]))\ncov_lac_hard = float(np.mean(sets_lac[hard_mask][np.arange(hard_mask.sum()), yc_te[hard_mask]]))\ncov_aps_all = float(np.mean(sets_aps[np.arange(len(yc_te)), yc_te]))\ncov_aps_hard = float(np.mean(sets_aps[hard_mask][np.arange(hard_mask.sum()), yc_te[hard_mask]]))\n\nprint(\"\\n=== Bagian B: Randomized APS vs LAC pada 5-Class Classification (Hard Subset Audit) ===\")\nprint(f\"LAC (1 - p_y) | Marg Cov={cov_lac_all:.4f} | Hard-Sample Cov={cov_lac_hard:.4f} | Avg Size={sets_lac.sum(1).mean():.3f}\")\nprint(f\"APS (CumProb) | Marg Cov={cov_aps_all:.4f} | Hard-Sample Cov={cov_aps_hard:.4f} | Avg Size={sets_aps.sum(1).mean():.3f}\")",
          "expectedOutput": "=== Bagian A: Scikit-Learn HistGBDT Quantile -> CQR vs Split Conformal ===\nSplit Conformal (Konstan) | Marg=0.909 | LowVar=1.000 | HighVar=0.782 | AvgW=13.54\nCQR Adaptif (Q=+1.028)   | Marg=0.920 | LowVar=1.000 | HighVar=0.880 | AvgW=11.52\n\n=== Bagian B: Randomized APS vs LAC pada 5-Class Classification (Hard Subset Audit) ===\nLAC (1 - p_y) | Marg Cov=0.8733 | Hard-Sample Cov=0.8725 | Avg Size=1.498\nAPS (CumProb) | Marg Cov=0.9067 | Hard-Sample Cov=0.9060 | Avg Size=1.816",
          "actualOutput": "=== Bagian A: Scikit-Learn HistGBDT Quantile -> CQR vs Split Conformal ===\nSplit Conformal (Konstan) | Marg=0.909 | LowVar=1.000 | HighVar=0.782 | AvgW=13.54\nCQR Adaptif (Q=+1.028)   | Marg=0.920 | LowVar=1.000 | HighVar=0.880 | AvgW=11.52\n\n=== Bagian B: Randomized APS vs LAC pada 5-Class Classification (Hard Subset Audit) ===\nLAC (1 - p_y) | Marg Cov=0.8733 | Hard-Sample Cov=0.8725 | Avg Size=1.498\nAPS (CumProb) | Marg Cov=0.9067 | Hard-Sample Cov=0.9060 | Avg Size=1.816",
