          "code": "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\n\nrng = np.random.default_rng(3049)\n\n# -----------------------------------------------------------------------------\n# Production Shift Audit: Covariate Shift Menumbangkan Split Conformal Standar\n# vs Weighted Conformal Prediction (Tibshirani et al. 2019) dengan Density-Ratio\n# -----------------------------------------------------------------------------\n# Kalibrasi: mayoritas trafik normal (x ~ N(0, 1))\nn_cal, n_test = 1500, 1500\nalpha = 0.10\n\nx_cal = rng.normal(loc=0.0, scale=1.0, size=n_cal)\n# Test (Covariate Shift!): lonjakan trafik musiman bergeser ke kanan (x ~ N(1.0, 1.0))\nx_te = rng.normal(loc=1.0, scale=1.0, size=n_test)\n\n# P(Y|X) tetap identik (pure covariate shift!), tetapi varians meningkat pada x besar\ndef sample_y(x: np.ndarray) -> tuple[np.ndarray, np.ndarray]:\n    mu = 1.5 * x\n    sig = 0.5 + 0.9 * np.exp(0.45 * x)\n    return mu + sig * rng.standard_normal(size=len(x)), mu\n\ny_cal, mu_cal = sample_y(x_cal)\ny_te, mu_te = sample_y(x_te)\n\ns_cal = np.abs(y_cal - mu_cal)\ns_te = np.abs(y_te - mu_te)\n\n# 1) Unweighted Split Conformal (gagal karena melanggar exchangeability!)\nq_unw = float(np.quantile(s_cal, np.ceil((n_cal + 1) * (1 - alpha)) / n_cal, method=\"higher\"))\ncov_unw = float(np.mean(s_te <= q_unw))\n\n# 2) Estimasi density ratio w(x) = P_test(x)/P_cal(x) via domain classifier (C=100 agar bebas bias regularisasi!)\nX_dom = np.concatenate([x_cal, x_te])[:, None]\ny_dom = np.concatenate([np.zeros(n_cal), np.ones(n_test)])\ndom_clf = LogisticRegression(C=100.0).fit(X_dom, y_dom)\n\n\ndef est_weight(x_arr: np.ndarray) -> np.ndarray:\n    # Eksponensial langsung log-odds domain classifier (tanpa kliping sempit!) * rasio prior\n    log_odds = dom_clf.decision_function(x_arr[:, None])\n    return np.exp(np.clip(log_odds, -12.0, 12.0)) * (n_cal / n_test)\n\n\nw_cal = est_weight(x_cal)\nw_te = est_weight(x_te)\n\n# Effective Sample Size (Kish ESS) untuk audit kelayakan importance weights\ness = float((np.sum(w_cal) ** 2) / np.sum(w_cal ** 2))\n\n# Weighted Conformal Quantile untuk tiap x_test\norder = np.argsort(s_cal)\ns_sorted = s_cal[order]\nw_sorted = w_cal[order]\nw_sum = float(np.sum(w_sorted))\nw_cumsum = np.cumsum(w_sorted)\n\nhits_w = np.empty(n_test, dtype=bool)\nq_w_list = np.empty(n_test, dtype=float)\nfor i in range(n_test):\n    denom = w_sum + w_te[i]\n    cdf = w_cumsum / denom\n    idx = int(np.searchsorted(cdf, 1.0 - alpha, side=\"left\"))\n    q_i = float(s_sorted[idx]) if idx < n_cal else float(\"inf\")\n    q_w_list[i] = q_i\n    hits_w[i] = s_te[i] <= q_i\n\nfinite_mask = np.isfinite(q_w_list)\nprint(f\"=== Audit Covariate Shift (Cal x~N(0,1) -> Test x~N(1.0,1), Target=90%) ===\")\nprint(f\"Kish Effective Sample Size (ESS): {ess:.1f} / {n_cal} ({ess / n_cal:.1%})\")\nprint(f\"Unweighted Split Conformal      : Coverage={cov_unw:.4f} (JATUH!) | Avg Width={2 * q_unw:.2f}\")\nprint(\n    f\"Weighted Conformal (DensRatio)  : Coverage={hits_w.mean():.4f} (PULIH!) | \"\n    f\"Avg Finite Width={2 * q_w_list[finite_mask].mean():.2f} | Inf Rate={(~finite_mask).mean():.2%}\"\n)",
          "expectedOutput": "=== Audit Covariate Shift (Cal x~N(0,1) -> Test x~N(1.0,1), Target=90%) ===\nKish Effective Sample Size (ESS): 615.0 / 1500 (41.0%)\nUnweighted Split Conformal      : Coverage=0.8113 (JATUH!) | Avg Width=5.21\nWeighted Conformal (DensRatio)  : Coverage=0.9187 (PULIH!) | Avg Finite Width=7.48 | Inf Rate=0.00%",
          "actualOutput": "=== Audit Covariate Shift (Cal x~N(0,1) -> Test x~N(1.0,1), Target=90%) ===\nKish Effective Sample Size (ESS): 615.0 / 1500 (41.0%)\nUnweighted Split Conformal      : Coverage=0.8113 (JATUH!) | Avg Width=5.21\nWeighted Conformal (DensRatio)  : Coverage=0.9187 (PULIH!) | Avg Finite Width=7.48 | Inf Rate=0.00%",
